SELECT ca_ret.ca_state AS returning_state, ca_ref.ca_state AS refunded_state, COUNT(*) AS return_cnt, SUM(wr.wr_net_loss) AS total_net_loss, AVG(wr.wr_return_amt_inc_tax) AS avg_return_amt_inc_tax, SUM(CASE WHEN wr.wr_return_quantity > 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS pct_multi_item_returns, RANK() OVER (ORDER BY SUM(wr.wr_net_loss) DESC) AS net_loss_rank FROM web_returns wr JOIN customer_address ca_ret ON wr.wr_returning_addr_sk = ca_ret.ca_address_sk JOIN customer_demographics cd_ret ON wr.wr_returning_cdemo_sk = cd_ret.cd_demo_sk JOIN customer_address ca_ref ON wr.wr_refunded_addr_sk = ca_ref.ca_address_sk JOIN customer_demographics cd_ref ON wr.wr_refunded_cdemo_sk = cd_ref.cd_demo_sk WHERE ca_ret.ca_state IN ('AZ', 'CO', 'PA') AND ca_ref.ca_state IN ('AZ', 'CO', 'PA') AND cd_ref.cd_credit_rating = 'A' AND wr.wr_return_amt_inc_tax > 100 AND ca_ret.ca_gmt_offset = -7.00 GROUP BY ca_ret.ca_state, ca_ref.ca_state HAVING COUNT(*) >= 10 ORDER BY total_net_loss DESC LIMIT 100
